dashboard.definition:
{
  "title": "Model Residency and Memory",
  "description": "Memory use per Mac inference host and macOS memory-kill, memory-pressure, and freeze events. Model load and unload timelines and per-process memory are not included.",
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$time.earliest$",
            "latest": "$time.latest$"
          }
        }
      }
    }
  },
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "time",
        "defaultValue": "-24h@h,now"
      }
    },
    "input_host": {
      "type": "input.dropdown",
      "title": "Host",
      "options": {
        "token": "host",
        "defaultValue": "*",
        "selectFirstSearchResult": false,
        "searchWhenChanged": true,
        "items": {
          "dataSources": {
            "primary": "ds_input_hosts"
          }
        }
      }
    }
  },
  "dataSources": {
    "ds_input_hosts": {
      "type": "ds.search",
      "options": {
        "query": "index=llm sourcetype=mlx:metrics | stats count BY host | eval label=host, value=host | append [| makeresults | eval label=\"All hosts\", value=\"*\"] | fields label value",
        "queryParameters": {
          "earliest": "-30d",
          "latest": "now"
        }
      }
    },
    "ds_host_memory_pct": {
      "type": "ds.search",
      "options": {
        "query": "index=llm sourcetype=mlx:metrics host=$host$ node_memory_used_percent=* | timechart span=5m avg(node_memory_used_percent) AS used_pct BY host limit=0 useother=f",
        "queryParameters": {
          "earliest": "$time.earliest$",
          "latest": "$time.latest$"
        }
      }
    },
    "ds_macmon_memory_pct": {
      "type": "ds.search",
      "options": {
        "query": "index=mac_perf sourcetype=\"macos:perf:macmon\" host=$host$ | dedup _time host | rename \"memory.ram_usage\" AS ram_used_bytes, \"memory.ram_total\" AS ram_total_bytes | where ram_total_bytes>0 | eval used_pct=round(100*ram_used_bytes/ram_total_bytes,1) | timechart span=5m avg(used_pct) AS used_pct BY host limit=0 useother=f",
        "queryParameters": {
          "earliest": "$time.earliest$",
          "latest": "$time.latest$"
        }
      }
    },
    "ds_macmon_pressure_pct": {
      "type": "ds.search",
      "options": {
        "query": "index=mac_perf sourcetype=\"macos:perf:macmon\" host=$host$ | dedup _time host | rename \"memory.pressure_percent\" AS pressure_pct | where isnotnull(pressure_pct) | timechart span=5m avg(pressure_pct) AS pressure_pct BY host limit=0 useother=f",
        "queryParameters": {
          "earliest": "$time.earliest$",
          "latest": "$time.latest$"
        }
      }
    },
    "ds_swap_used": {
      "type": "ds.search",
      "options": {
        "query": "index=llm sourcetype=mlx:metrics host=$host$ node_memory_swap_used_bytes=* | timechart span=5m avg(node_memory_swap_used_bytes) AS swap_used_bytes BY host limit=0 useother=f",
        "queryParameters": {
          "earliest": "$time.earliest$",
          "latest": "$time.latest$"
        }
      }
    },
    "ds_memory_event_counts": {
      "type": "ds.search",
      "options": {
        "query": "index=os host=$host$ ((sourcetype=\"macos:unified_log\" (\"jetsam\" OR \"memorystatus\" OR \"memory pressure\" OR \"userspace watchdog timeout\" OR \"synchronize timed out\" OR \"failed to act\" OR \"Clearing datagram buffer\" OR \"gpu hang\" OR \"GPU restart\")) OR (sourcetype=\"macos:crashreport\" (source=\"*JetsamEvent*\" OR \"userspace watchdog timeout\"))) | eval category=case(match(_raw,\"(?i)jetsam|memorystatus\") OR match(source,\"JetsamEvent\"),\"memory kill\", match(_raw,\"(?i)memory pressure\"),\"memory pressure\", true(),\"freeze or watchdog\") | timechart span=1h count BY category limit=0 useother=f",
        "queryParameters": {
          "earliest": "$time.earliest$",
          "latest": "$time.latest$"
        }
      }
    },
    "ds_memory_event_table": {
      "type": "ds.search",
      "options": {
        "query": "index=os host=$host$ ((sourcetype=\"macos:unified_log\" (\"jetsam\" OR \"memorystatus\" OR \"memory pressure\" OR \"userspace watchdog timeout\" OR \"synchronize timed out\" OR \"failed to act\" OR \"Clearing datagram buffer\" OR \"gpu hang\" OR \"GPU restart\")) OR (sourcetype=\"macos:crashreport\" (source=\"*JetsamEvent*\" OR \"userspace watchdog timeout\"))) | eval category=case(match(_raw,\"(?i)jetsam|memorystatus\") OR match(source,\"JetsamEvent\"),\"memory kill\", match(_raw,\"(?i)memory pressure\"),\"memory pressure\", true(),\"freeze or watchdog\") | eval raw_excerpt=substr(_raw,1,240) | table _time host sourcetype category raw_excerpt | sort 0 - _time | head 200",
        "queryParameters": {
          "earliest": "$time.earliest$",
          "latest": "$time.latest$"
        }
      }
    }
  },
  "visualizations": {
    "viz_host_memory_pct": {
      "type": "splunk.line",
      "title": "Memory used by host (node metrics)",
      "description": "Average of node_memory_used_percent per 5 minutes, from the system-metrics feed.",
      "dataSources": {
        "primary": "ds_host_memory_pct"
      },
      "options": {}
    },
    "viz_macmon_memory_pct": {
      "type": "splunk.line",
      "title": "Memory used by host (macmon)",
      "description": "RAM used divided by RAM total, from the macmon exec input.",
      "dataSources": {
        "primary": "ds_macmon_memory_pct"
      },
      "options": {}
    },
    "viz_macmon_pressure_pct": {
      "type": "splunk.line",
      "title": "Memory pressure by host (macmon)",
      "description": "Average of the macmon memory pressure percentage per 5 minutes.",
      "dataSources": {
        "primary": "ds_macmon_pressure_pct"
      },
      "options": {}
    },
    "viz_swap_used": {
      "type": "splunk.line",
      "title": "Swap used by host",
      "description": "Average of node_memory_swap_used_bytes per 5 minutes, from the system-metrics feed.",
      "dataSources": {
        "primary": "ds_swap_used"
      },
      "options": {}
    },
    "viz_memory_event_counts": {
      "type": "splunk.line",
      "title": "Memory kill, memory pressure, and freeze events per hour",
      "description": "Counts from the macOS unified log and crash reports, grouped by category.",
      "dataSources": {
        "primary": "ds_memory_event_counts"
      },
      "options": {}
    },
    "viz_memory_event_table": {
      "type": "splunk.table",
      "title": "Memory and freeze events",
      "description": "Most recent 200 matching events. Excerpt is the first 240 characters of the raw event.",
      "dataSources": {
        "primary": "ds_memory_event_table"
      },
      "options": {}
    }
  },
  "layout": {
    "type": "grid",
    "options": {
      "width": 1440,
      "height": 1320,
      "display": "auto-scale"
    },
    "structure": [
      {"item": "viz_host_memory_pct", "type": "block", "position": {"x": 0, "y": 0, "w": 720, "h": 320}},
      {"item": "viz_macmon_memory_pct", "type": "block", "position": {"x": 720, "y": 0, "w": 720, "h": 320}},
      {"item": "viz_macmon_pressure_pct", "type": "block", "position": {"x": 0, "y": 320, "w": 720, "h": 260}},
      {"item": "viz_swap_used", "type": "block", "position": {"x": 720, "y": 320, "w": 720, "h": 260}},
      {"item": "viz_memory_event_counts", "type": "block", "position": {"x": 0, "y": 580, "w": 1440, "h": 300}},
      {"item": "viz_memory_event_table", "type": "block", "position": {"x": 0, "y": 880, "w": 1440, "h": 440}}
    ],
    "globalInputs": ["input_time", "input_host"]
  }
}
